function buildQuestions() {
  const mcqBank = [
    ["When I see something new and confusing, I usually...", ["Want to take it apart and figure it out", "Ask someone else to explain it", "Feel a bit overwhelmed", "Ignore it and move on"]],
    ["If I had a free afternoon with no plans, I would most likely...", ["Start a project I've been curious about", "Read something I've never read before", "Hang out with friends", "Relax and watch something"]],
    ["When a teacher asks a question nobody knows, I...", ["Try to guess an answer out loud", "Think quietly about possibilities", "Wait for someone else to answer", "Look it up later"]],
    ["My favorite kind of question is one that...", ["Has no single right answer", "Has one clear correct answer", "I already know the answer to", "Someone else can answer for me"]],
    ["I feel most curious when I'm...", ["Exploring a place I've never been", "Reading facts about animals or space", "Trying a new hobby", "Talking with someone new"]],
    ["When I finish a book or show I loved, I usually...", ["Look for more like it", "Talk about it with friends", "Think about it quietly", "Move on to the next thing"]],
    ["When I have a big problem to solve, I first...", ["Break it into smaller pieces", "Ask for help right away", "Try the first idea that comes to mind", "Take a break before starting"]],
    ["If my first idea doesn't work, I usually...", ["Try a completely different approach", "Tweak the same idea slightly", "Feel frustrated and stop", "Ask someone to solve it for me"]],
    ["I enjoy activities where I get to...", ["Build or design something new", "Follow clear step-by-step instructions", "Repeat something I'm already good at", "Watch others do it first"]],
    ["When drawing or writing something creative, I...", ["Like to invent my own style", "Prefer to copy an example closely", "Get nervous about being judged", "Don't enjoy it much"]],
    ["A tricky puzzle makes me feel...", ["Excited to crack it", "Curious but a little nervous", "Bored quickly", "Annoyed"]],
    ["If two of my ideas conflict, I...", ["Test both and see what happens", "Pick whichever seems safest", "Ask someone else to decide", "Stick with my very first idea"]],
    ["In a group project, I usually...", ["Suggest ideas and listen to others", "Prefer to do my own part alone", "Wait for someone to lead", "Take charge of everything myself"]],
    ["When a teammate disagrees with my idea, I...", ["Ask them why and consider it", "Explain my reasoning and move on", "Feel upset but stay quiet", "Insist on my own idea"]],
    ["After I make a mistake, I usually...", ["Figure out what went wrong and retry", "Feel bad about it for a while", "Ask someone to fix it", "Avoid that activity afterward"]],
  ];

  const textBank = [
    "Describe a time you were really curious about something. What did you do to learn more about it?",
    "Tell us about a problem you solved in a creative way. What made your solution unusual?",
    "Describe a time you worked with someone who saw things differently than you. What happened?",
  ];

  const qs = [];
  let mcqI = 0, textI = 0, id = 1;
  for (let section = 1; section <= 3; section++) {
    for (let i = 0; i < 6; i++) {
      const useText = i === 5 && textI < textBank.length;
      if (useText) {
        qs.push({ id: id++, section, type: "text", prompt: textBank[textI++] });
      } else {
        const [prompt, options] = mcqBank[mcqI++ % mcqBank.length];
        qs.push({ id: id++, section, type: "mcq", prompt, options });
      }
    }
  }
  return qs;
}
const QUESTIONS = buildQuestions();

