function PillButton({ children, onClick, variant = "navy", disabled, style, icon: Icon, type = "button" }) {
  const variants = {
    navy: { background: C.navy, color: C.white },
    yellow: { background: C.yellow, color: C.navy },
    sky: { background: C.sky, color: C.white },
    pink: { background: C.pink, color: C.white },
    ghost: { background: "transparent", color: C.navy, border: `1.5px solid ${C.navy}` },
    white: { background: C.white, color: C.navy, border: "1.5px solid #E3DFD6" },
  };
  return (
    <button
      type={type}
      className="qq-pill-btn"
      disabled={disabled}
      onClick={onClick}
      style={{ ...variants[variant], ...style }}
    >
      {Icon && <Icon size={17} />}
      {children}
    </button>
  );
}

