function Toast({ text, onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 2600);
    return () => clearTimeout(t);
  }, []);
  return (
    <div
      className="qq-fade-in"
      style={{
        position: "fixed", bottom: 26, left: "50%", transform: "translateX(-50%)",
        background: C.navy, color: C.white, padding: "13px 22px", borderRadius: 999,
        fontSize: 14, fontWeight: 600, boxShadow: "0 12px 30px -8px rgba(0,0,0,0.4)",
        zIndex: 999, display: "flex", alignItems: "center", gap: 10, maxWidth: "88%",
      }}
    >
      🔌 {text}
    </div>
  );
}

