function ScreenAssessmentQuestion({ go, idx, setIdx, answers, setAnswer, timeLeft }) {
  const q = QUESTIONS[idx];
  const section = q.section;
  const questionInSection = idx - (section - 1) * 6 + 1;
  const mm = String(Math.floor(timeLeft / 60)).padStart(2, "0");
  const ss = String(timeLeft % 60).padStart(2, "0");
  const isLast = idx === QUESTIONS.length - 1;

  return (
    <div className="qq-root">
      <div style={{ background: C.navy, padding: "20px 40px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", maxWidth: 780, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <LogoMark size={26} /> <Wordmark dark={false} size={16} />
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, background: "rgba(255,255,255,0.1)", padding: "7px 16px", borderRadius: 999 }}>
            <Clock size={15} color={timeLeft < 300 ? C.pink : C.white} />
            <span style={{ color: timeLeft < 300 ? C.pink : C.white, fontWeight: 700, fontSize: 14, fontVariantNumeric: "tabular-nums" }}>{mm}:{ss}</span>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: 780, margin: "0 auto", padding: "30px 24px 0" }}>
        <div style={{ fontSize: 13, fontWeight: 700, color: C.blue, marginBottom: 8 }}>
          SECTION {section} OF 3 — {SECTION_TITLES[section - 1].toUpperCase()}
        </div>
        <div style={{ height: 10, background: "#EFE9DC", borderRadius: 999, overflow: "hidden", marginBottom: 10 }}>
          <div style={{ height: "100%", width: `${((idx + 1) / QUESTIONS.length) * 100}%`, background: `linear-gradient(90deg, ${C.yellow}, ${C.pink}, ${C.sky})`, borderRadius: 999, transition: "width .3s ease" }} />
        </div>
        <div style={{ fontSize: 12.5, color: C.inkSoft, marginBottom: 24 }}>
          Question {idx + 1} of {QUESTIONS.length} &nbsp;·&nbsp; Question {questionInSection} of 6 in this section
        </div>
      </div>

      <div style={{ maxWidth: 780, margin: "0 auto", padding: "0 24px 60px" }}>
        <div key={q.id} className="qq-card qq-fade-in" style={{ padding: "36px 38px" }}>
          <h2 className="qq-heading" style={{ color: C.navy, fontSize: 21, marginBottom: 22, lineHeight: 1.4 }}>{q.prompt}</h2>
          {q.type === "mcq" ? (
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {q.options.map((opt) => (
                <div
                  key={opt}
                  className={`qq-mcq-option ${answers[q.id] === opt ? "selected" : ""}`}
                  onClick={() => setAnswer(q.id, opt)}
                >
                  <div style={{
                    width: 20, height: 20, borderRadius: "50%", flexShrink: 0,
                    border: `2px solid ${answers[q.id] === opt ? C.blue : "#CFC9BC"}`,
                    display: "flex", alignItems: "center", justifyContent: "center",
                  }}>
                    {answers[q.id] === opt && <div style={{ width: 10, height: 10, borderRadius: "50%", background: C.blue }} />}
                  </div>
                  {opt}
                </div>
              ))}
            </div>
          ) : (
            <textarea
              className="qq-input"
              rows={5}
              placeholder="Type your answer here..."
              value={answers[q.id] || ""}
              onChange={(e) => setAnswer(q.id, e.target.value)}
              style={{ resize: "vertical" }}
            />
          )}

          <div style={{ display: "flex", justifyContent: "space-between", marginTop: 30 }}>
            <PillButton variant="ghost" icon={ChevronLeft} disabled={idx === 0} onClick={() => setIdx(idx - 1)}>Back</PillButton>
            {!isLast ? (
              <PillButton variant="navy" onClick={() => setIdx(idx + 1)}>
                Next <ChevronRight size={17} />
              </PillButton>
            ) : (
              <PillButton variant="yellow" onClick={() => go("submissionConfirm")}>
                Submit Quest <CheckCircle2 size={17} />
              </PillButton>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

