/* ------------------------------ Admin screens ---------------------------- */

function ScreenAdminDashboard({ go, students, setStudents, openReview, notify }) {
  const [selected, setSelected] = useState([]);
  const selectable = students.filter((s) => s.status === "submitted" || s.status === "pending_review");
  const allSelected = selectable.length > 0 && selectable.every((s) => selected.includes(s.id));

  const toggle = (id) => setSelected((sel) => (sel.includes(id) ? sel.filter((x) => x !== id) : [...sel, id]));
  const toggleAll = () => setSelected(allSelected ? [] : selectable.map((s) => s.id));

  const sendSelected = () => {
    setStudents((list) => list.map((s) => (selected.includes(s.id) ? { ...s, status: "sent" } : s)));
    notify(`${selected.length} report${selected.length > 1 ? "s" : ""} queued via SendGrid / Supabase Edge Function.`);
    setSelected([]);
  };

  return (
    <div className="qq-root">
      <TopBar name="Admin" email="admin@edjuvenate.com" go={go} adminMode />
      <div style={{ maxWidth: 1000, margin: "0 auto", padding: "40px 24px 80px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", marginBottom: 22, flexWrap: "wrap", gap: 14 }}>
          <div>
            <span className="qq-badge" style={{ background: C.navy, color: C.white }}>Admin Dashboard</span>
            <h1 className="qq-heading" style={{ color: C.navy, fontSize: 28, margin: "12px 0 4px" }}>Students</h1>
            <p style={{ color: C.inkSoft, fontSize: 14 }}>Select students to send their approved Qriosity reports.</p>
          </div>
          <div style={{ display: "flex", gap: 10 }}>
            <PillButton variant="ghost" onClick={() => go("adminPipeline")} icon={ListChecks}>Pipeline View</PillButton>
            <PillButton
              variant={selected.length ? "pink" : "white"}
              disabled={selected.length === 0}
              icon={Send}
              onClick={sendSelected}
            >
              Send Reports to Selected {selected.length > 0 ? `(${selected.length})` : ""}
            </PillButton>
          </div>
        </div>

        <div className="qq-card" style={{ overflow: "hidden" }}>
          <div style={{ display: "grid", gridTemplateColumns: "48px 2fr 1fr 1.3fr 1fr 1fr", padding: "16px 24px", borderBottom: "1px solid #F0EBE0", background: "#FBF8F2", fontSize: 12.5, fontWeight: 700, color: C.inkSoft, textTransform: "uppercase", letterSpacing: "0.03em" }}>
            <div onClick={toggleAll} style={{ cursor: "pointer", display: "flex" }}>
              {allSelected ? <CheckSquare size={18} color={C.blue} /> : <Square size={18} color="#C7C0B2" />}
            </div>
            <div>Name</div>
            <div>Grade</div>
            <div>Status</div>
            <div>Submitted</div>
            <div>Report</div>
          </div>
          {students.map((s) => {
            const canSelect = s.status === "submitted" || s.status === "pending_review";
            const isChecked = selected.includes(s.id);
            return (
              <div key={s.id} style={{ display: "grid", gridTemplateColumns: "48px 2fr 1fr 1.3fr 1fr 1fr", padding: "16px 24px", borderBottom: "1px solid #F5F1E9", alignItems: "center", fontSize: 14.5 }}>
                <div onClick={() => canSelect && toggle(s.id)} style={{ cursor: canSelect ? "pointer" : "default", display: "flex" }}>
                  {canSelect ? (
                    isChecked ? <CheckSquare size={18} color={C.blue} /> : <Square size={18} color="#C7C0B2" />
                  ) : (
                    <Square size={18} color="#E9E4D9" />
                  )}
                </div>
                <div style={{ fontWeight: 600, color: C.navy }}>{s.name}</div>
                <div style={{ color: C.inkSoft }}>{s.grade}</div>
                <div><StatusBadge status={s.status} /></div>
                <div style={{ color: C.inkSoft }}>{s.submittedAt}</div>
                <div>
                  {s.status !== "not_started" ? (
                    <span style={{ color: C.blue, fontWeight: 700, cursor: "pointer", fontSize: 13.5 }} onClick={() => openReview(s.id)}>
                      View →
                    </span>
                  ) : (
                    <span style={{ color: "#C7C0B2", fontSize: 13.5 }}>—</span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function ScreenAdminReportReview({ go, student, setStudents, notify }) {
  const [letter, setLetter] = useState(LETTER_TO_PARENTS);
  const [editing, setEditing] = useState(false);

  const approveAndSend = () => {
    setStudents((list) => list.map((s) => (s.id === student.id ? { ...s, status: "sent" } : s)));
    notify(`Report for ${student.name} approved and sent via SendGrid (mocked).`);
    go("adminDashboard");
  };
  const regenerate = () => notify(`Re-running AI scoring pipeline (Gemini) for ${student.name}.`);
  const saveEdit = () => { setEditing(false); notify(`Edited letter saved to Supabase (mocked) for ${student.name}.`); };

  return (
    <div className="qq-root">
      <TopBar name="Admin" email="admin@edjuvenate.com" go={go} adminMode />
      <div style={{ maxWidth: 720, margin: "0 auto", padding: "40px 24px 90px" }}>
        <div style={{ marginBottom: 20, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <span style={{ color: C.blue, fontWeight: 700, cursor: "pointer", fontSize: 13.5 }} onClick={() => go("adminDashboard")}>← Back to dashboard</span>
          <StatusBadge status={student.status} />
        </div>
        <ReportCard studentName={student.name} editableLetter={true} letter={letter} setLetter={setLetter} editing={editing} />

        <div className="qq-card" style={{ padding: "22px 28px", marginTop: 20, display: "flex", gap: 12, flexWrap: "wrap" }}>
          {!editing ? (
            <>
              <PillButton variant="navy" icon={Send} onClick={approveAndSend}>Approve &amp; Send</PillButton>
              <PillButton variant="ghost" icon={RefreshCw} onClick={regenerate}>Regenerate</PillButton>
              <PillButton variant="white" icon={Pencil} onClick={() => setEditing(true)}>Edit</PillButton>
            </>
          ) : (
            <PillButton variant="navy" icon={CheckCircle2} onClick={saveEdit}>Save Edit</PillButton>
          )}
        </div>
      </div>
    </div>
  );
}

