function ScreenAdminPipeline({ go, students }) {
  const notStarted = students.filter((s) => s.status === "not_started");
  const submitted = students.filter((s) => s.status === "submitted");
  const pending = students.filter((s) => s.status === "pending_review");
  const sent = students.filter((s) => s.status === "sent");
  return (
    <div className="qq-root">
      <TopBar name="Admin" email="admin@edjuvenate.com" go={go} adminMode />
      <div style={{ maxWidth: 1100, margin: "0 auto", padding: "40px 24px 90px" }}>
        <span style={{ color: C.blue, fontWeight: 700, cursor: "pointer", fontSize: 13.5 }} onClick={() => go("adminDashboard")}>← Back to dashboard</span>
        <h1 className="qq-heading" style={{ color: C.navy, fontSize: 28, margin: "14px 0 6px" }}>Submissions Pipeline</h1>
        <p style={{ color: C.inkSoft, fontSize: 14, marginBottom: 30 }}>A live look at where every student stands, quest to inbox.</p>
        <div style={{ display: "flex", gap: 26, flexWrap: "wrap" }}>
          <PipelineColumn title="Not Submitted" color="#B5AE9F" icon={Clock} students={notStarted} emptyText="Everyone has started 🎉" />
          <PipelineColumn title="Submitted — Awaiting Review" color={C.yellow} icon={BookOpen} students={submitted} emptyText="Nothing waiting" />
          <PipelineColumn title="Pending Review" color={C.pink} icon={Wand2} students={pending} emptyText="Nothing pending" />
          <PipelineColumn title="Sent to Parents" color="#1B7D45" icon={CheckCircle2} students={sent} emptyText="Nothing sent yet" />
        </div>
      </div>
    </div>
  );
}

/* ================================= App ==================================== */

export default function App() {
  const [screen, setScreen] = useState("studentLogin");
  const [toast, setToast] = useState(null);
  const [questComplete, setQuestComplete] = useState(false);

  const [qIdx, setQIdx] = useState(0);
  const [answers, setAnswers] = useState({});
  const [timeLeft, setTimeLeft] = useState(45 * 60);

  const [students, setStudents] = useState(STUDENT_SEED);
  const [reviewId, setReviewId] = useState(1);

  const notify = (text) => setToast(text);
  const setAnswer = (id, val) => setAnswers((a) => ({ ...a, [id]: val }));
  const openReview = (id) => { setReviewId(id); setScreen("adminReportReview"); };

  // Countdown only while actively taking the quest
  useEffect(() => {
    if (screen !== "assessmentQuestion") return;
    if (timeLeft <= 0) return;
    const t = setInterval(() => setTimeLeft((v) => Math.max(0, v - 1)), 1000);
    return () => clearInterval(t);
  }, [screen, timeLeft]);

  const go = (key) => {
    window.scrollTo(0, 0);
    setScreen(key);
  };

  const reviewStudent = students.find((s) => s.id === reviewId) || students[0];

  let content;
  switch (screen) {
    case "signup":
      content = <ScreenSignUp go={go} notify={notify} />;
      break;
    case "studentLogin":
      content = <ScreenStudentLogin go={go} notify={notify} />;
      break;
    case "studentDashboard":
      content = <ScreenStudentDashboard go={go} questComplete={questComplete} />;
      break;
    case "assessmentIntro":
      content = <ScreenAssessmentIntro go={go} resetTimer={() => { setTimeLeft(45 * 60); setQIdx(0); }} />;
      break;
    case "assessmentQuestion":
      content = (
        <ScreenAssessmentQuestion
          go={go} idx={qIdx} setIdx={setQIdx} answers={answers} setAnswer={setAnswer} timeLeft={timeLeft}
        />
      );
      break;
    case "submissionConfirm":
      content = <ScreenSubmissionConfirm go={go} markComplete={() => setQuestComplete(true)} />;
      break;
    case "studentReport":
      content = <ScreenStudentReport go={go} />;
      break;
    case "adminLogin":
      content = <ScreenAdminLogin go={go} notify={notify} />;
      break;
    case "adminDashboard":
      content = <ScreenAdminDashboard go={go} students={students} setStudents={setStudents} openReview={openReview} notify={notify} />;
      break;
    case "adminReportReview":
      content = <ScreenAdminReportReview go={go} student={reviewStudent} setStudents={setStudents} notify={notify} />;
      break;
    case "adminPipeline":
      content = <ScreenAdminPipeline go={go} students={students} />;
      break;
    default:
      content = <ScreenStudentLogin go={go} notify={notify} />;
  }

  return (
    <div>
      <GlobalStyle />
      {content}
      <DevNav current={screen} go={go} />
      {toast && <Toast text={toast} onDone={() => setToast(null)} />}
    </div>
  );
}